with valid_store_sales as (select * from store_sales where not (units between 29 and 30 and (revenue is not null or revenue between 2200 and 2700))), store_id_summary as (select store_id, max(sale_date) as last_sale_date, round(stddev(units), 2) as stddev_units from valid_store_sales group by store_id) select store_id, last_sale_date, stddev_units from store_id_summary where stddev_units >= 52 order by stddev_units desc, store_id desc;
